import{bR as a,aL as e,v as l,H as o}from"./chunks/framework.DRjBupPc.js";const b=JSON.parse('{"title":"LLMs.txt","description":"使用 TinyRobot 的 AI 友好文档，查找组件说明、使用方法和示例。","frontmatter":{"title":"LLMs.txt","kind":"agent-doc","description":"使用 TinyRobot 的 AI 友好文档，查找组件说明、使用方法和示例。","status":"stable","keywords":["LLMs.txt","AI 文档","TinyRobot"]},"headers":[],"relativePath":"agents/llms-txt.md","filePath":"agents/llms-txt.md"}'),i={name:"agents/llms-txt.md"};function r(s,t,n,d,c,h){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="llms-txt" tabindex="-1">LLMs.txt <a class="header-anchor" href="#llms-txt" aria-label="Permalink to &quot;LLMs.txt&quot;">​</a></h1><blockquote><p>想让 AI 助手更了解 TinyRobot？可以把下面的文档提供给它，让它依据项目文档回答问题或协助编写代码。</p></blockquote><h2 id="提供哪些内容" tabindex="-1">提供哪些内容？ <a class="header-anchor" href="#提供哪些内容" aria-label="Permalink to &quot;提供哪些内容？&quot;">​</a></h2><p>这里有两份适合 AI 阅读的文档：</p><ul><li><a href="../llms.txt"><code>llms.txt</code></a>：精简的文档目录，帮助 AI 快速了解 TinyRobot 文档涵盖的主题，并找到相关内容。</li><li><a href="../llms-full.txt"><code>llms-full.txt</code></a>：汇集更完整的文档说明和示例，适合需要较多背景信息或跨多个主题查阅时使用。</li></ul><h2 id="应该从哪一份开始" tabindex="-1">应该从哪一份开始？ <a class="header-anchor" href="#应该从哪一份开始" aria-label="Permalink to &quot;应该从哪一份开始？&quot;">​</a></h2><p>如果你还不确定要查什么，先提供 <code>llms.txt</code>，让 AI 了解文档范围，再根据问题补充相关内容。这样通常能更快定位到需要的信息。</p><p>如果问题涉及多个组件、配置步骤或较完整的实现示例，可以提供 <code>llms-full.txt</code>，让 AI 在更完整的背景下回答。它包含的信息更多，适合需要深入查阅的任务。</p><h2 id="如何在-ai-工具中使用" tabindex="-1">如何在 AI 工具中使用？ <a class="header-anchor" href="#如何在-ai-工具中使用" aria-label="Permalink to &quot;如何在 AI 工具中使用？&quot;">​</a></h2><h3 id="支持添加文档链接的工具" tabindex="-1">支持添加文档链接的工具 <a class="header-anchor" href="#支持添加文档链接的工具" aria-label="Permalink to &quot;支持添加文档链接的工具&quot;">​</a></h3><p>如果你使用的工具支持添加文档链接或项目知识库，可以将 <code>llms.txt</code> 添加为文档入口。遇到需要完整背景的问题时，再添加 <code>llms-full.txt</code>。</p><h3 id="支持读取链接的聊天助手" tabindex="-1">支持读取链接的聊天助手 <a class="header-anchor" href="#支持读取链接的聊天助手" aria-label="Permalink to &quot;支持读取链接的聊天助手&quot;">​</a></h3><p>在提问时附上文档链接，并说明你希望 AI 根据 TinyRobot 文档回答。例如：</p><blockquote><p>请参考 TinyRobot 文档，说明 Bubble 组件如何使用，并给出包含必要导入语句的 Vue 示例。若文档没有说明某个 API，请指出这一点，不要猜测。</p></blockquote><p>不同 AI 工具读取网页链接的能力有所不同。如果工具无法直接读取链接，可以打开文档并将相关内容粘贴到对话中。</p><h2 id="什么时候使用" tabindex="-1">什么时候使用？ <a class="header-anchor" href="#什么时候使用" aria-label="Permalink to &quot;什么时候使用？&quot;">​</a></h2><p>你可以在以下场景中使用这些文档：</p><ul><li>了解 TinyRobot 提供了哪些组件和功能；</li><li>查找组件的使用方法、配置方式和示例；</li><li>请 AI 协助编写或调整 TinyRobot Vue 代码；</li><li>让 AI 根据项目文档解释已有实现或排查使用问题。</li></ul><p>提供相关文档有助于 AI 给出更贴合 TinyRobot 的回答；具体结果仍取决于所用工具能否读取这些内容，以及问题本身提供的信息是否充分。</p>',19)])])}const p=a(i,[["render",r]]);export{b as __pageData,p as default};
